package net.minecraft.client;
import net.minecraft.item.ItemStack;public class Minecraft {public Player player=new Player();public Object world=new Object(),currentScreen;public Controller playerController=new Controller();public static class Inventory{public int currentItem;public ItemStack cursor=ItemStack.EMPTY;public java.util.List<ItemStack> mainInventory=new java.util.ArrayList<>(java.util.Collections.nCopies(36,ItemStack.EMPTY));public ItemStack getStackInSlot(int i){return mainInventory.get(i);}public ItemStack getItemStack(){return cursor;}}public static class Container{public int windowId=0;}public static class Player{public boolean isDead;public Inventory inventory=new Inventory();public Container inventoryContainer=new Container(),openContainer=inventoryContainer;}public static class Controller{public int clicks;public void windowClick(int window,int source,int destination,net.minecraft.inventory.ClickType type,Player player){if(window!=0||type!=net.minecraft.inventory.ClickType.SWAP)throw new AssertionError("Inventory protocol");ItemStack old=player.inventory.mainInventory.get(destination);player.inventory.mainInventory.set(destination,player.inventory.mainInventory.get(source));player.inventory.mainInventory.set(source,old);clicks++;}}}